skill.procedure:
def apply(inputs, premises):
    timing_ok = inputs["payment_upon_or_after_termination"] == premises["required_timing"]
    cause_ok = inputs["termination_cause"] in premises["qualifying_termination_causes"]
    if timing_ok and cause_ok:
        answer = "Entailment"
    else:
        answer = "Contradiction"
    return {"answer": answer}
